  "E2E-13": {
    summary: "同一个 Commerce 入口严格区分未支付 Cancel、授权后未捕获 Void 与已捕获后的标准 Refund，Payment 在锁内作权威分支判断。",
    participants: ["operations", "operations_console", "operations_console_bff", "client_system", "client_api", "api_gateway", "commerce", "payment", "acquirer", "finance", "platform"],
    messages: [
      { from: "client_system", to: "api_gateway", label: "COM-I05 Cancel：POST /api/v1/orders/{orderNo}/cancel；Bearer Credential + Idempotency-Key，无 Body、无外部 Expected Version", kind: "sync" },
      { from: "api_gateway", to: "platform", label: "PLT-I03 只携带 opaque Credential 校验 PHC verifier；不提交可覆盖的 Tenant、Client 或 required Scope，无效/过期 Credential 失败关闭", kind: "sync" },
      { from: "platform", to: "api_gateway", label: "返回 trusted tenant_id、tenant_type=CLIENT、owner_ref_id、credential_id 与 effective ACTIVE scopes；Credential/Tenant 无效映射 401，歧义或技术依赖失败映射 503", kind: "sync" },
      { from: "api_gateway", to: "client_api", label: "Gateway 精确要求 orders.cancel 后每个 HTTP 尝试只转发一次；保留 Idempotency-Key，只注入 X-Request-Id、X-Gateway-Client-Id 与 X-Gateway-Credential-Id，不下传 Authorization、Tenant、Scope、Route 或 Channel", kind: "sync" },
      { from: "client_api", to: "commerce", label: "按可信 Client + CANCEL_ORDER + Key 和公开 orderNo 提交；Commerce 拥有逻辑幂等和归属校验，错误归属与不存在统一 404", kind: "sync" },
      { from: "commerce", to: "payment", label: "解析 orderNo 后内部使用 order_id 和锁/CAS，并以确定性子幂等键调用 PAY-I12 终止唯一 Payment Intent；前置条件是没有成功 Authorization、Capture 或 Sale，且没有已提交或 UNKNOWN 渠道结果", kind: "sync" },
      { from: "payment", to: "payment", label: "没有 Attempt 时直接终止；Provider 提交前的 Attempt 以 FAILED / CANCELLED_BEFORE_PROVIDER_SUBMIT 收敛并释放 Risk Reservation", kind: "sync" },
      { from: "payment", to: "commerce", label: "返回 TERMINATED 后 Commerce 才以 CAS 将 Order/Session 置为 CANCELLED、写 status_reason_code 并发布 OrderCancelled", kind: "sync" },
      { from: "commerce", to: "commerce", label: "取消事务同事务冻结 order.cancelled 不可变公开快照并登记 ClientWebhookRequested；不产生 Finance 事实或消费者财政凭证", kind: "sync" },
      { from: "commerce", to: "platform", label: "提交已冻结的 order.cancelled ClientWebhookRequested；重试保持同一 Event ID 和 Body", kind: "async" },
      { from: "payment", to: "acquirer", label: "alt：Provider 已提交或结果 UNKNOWN 时先执行 Query，不猜测未支付", kind: "sync" },
      { from: "payment", to: "commerce", label: "alt：返回 PENDING（reason_code=PAYMENT_IN_PROGRESS）保持 Order 开放；若查询发现授权成功则返回 REVERSAL_REQUIRED，Cancel 不会静默升级为 Reversal", kind: "sync" },
      { from: "operations", to: "operations_console", label: "对需要整体撤销的订单发起 Reversal", kind: "sync" },
      { from: "operations_console", to: "api_gateway", label: "提交 COM-I08 Reversal（order_id、Expected Version、Command Idempotency Key）", kind: "sync" },
      { from: "api_gateway", to: "operations_console_bff", label: "路由统一撤销命令", kind: "sync" },
      { from: "operations_console_bff", to: "commerce", label: "提交 COM-I08 Reversal；BFF 不编排 Payment 或 Finance", kind: "sync" },
      { from: "commerce", to: "payment", label: "调用 PAY-I13；Payment 锁定 Intent、Attempt、Action 与 Provider Transaction Ref，并以 Expected Version/CAS 原子解析和执行", kind: "sync" },
      { from: "payment", to: "commerce", label: "alt：PAY-I13 没有成功渠道结果时返回 USE_CANCEL；Commerce 以确定性子幂等键调用 PAY-I12", kind: "sync" },
      { from: "payment", to: "acquirer", label: "alt：授权成功但未 Capture 时冻结原 Authorization Ref、阻止后续 Capture，并创建精确目标的 Void（VOID Action）", kind: "sync" },
      { from: "acquirer", to: "payment", label: "返回 Void 权威终态；成功后 Attempt=VOIDED / AUTHORIZATION_VOIDED、Intent=CANCELLED，并释放 Risk Reservation", kind: "sync" },
      { from: "payment", to: "commerce", label: "PaymentIntentTerminated；Commerce 将 Order/Session 置为 CANCELLED，不创建 Refund Request，Finance 不入账", kind: "async" },
      { from: "payment", to: "commerce", label: "alt：SALE 或全额 Capture 后返回 REFUND_REQUIRED、原成功 Attempt 与 captured_amount，由 Commerce 新建 Commerce Refund Request（标准全额 Refund）", kind: "sync" },
      { from: "commerce", to: "commerce", label: "以 OPERATIONS 来源创建新的 Commerce Refund Request，并原子占用 Order Refund Position", kind: "sync" },
      { from: "commerce", to: "payment", label: "本地预占后直接调用 PAY-I04，携带 commerce_refund_request_id、order_id、refund_amount 与 currency 执行标准 Channel Refund；不创建 Reversal 表或 REVERSAL Payment Action", kind: "sync" },
      { from: "payment", to: "payment", label: "锁定 Payment Refund Position，以 Version/CAS 原子增加 reserved_amount 并创建唯一 Channel Refund", kind: "sync" },
      { from: "payment", to: "commerce", label: "RefundSucceeded 驱动 Refund Request 与 Position 收敛；Order 仍保持 PAID", kind: "async" },
      { from: "payment", to: "finance", label: "RefundSucceeded 驱动既有退款账务、财政更正与 Credit Note 链", kind: "async" },
      { from: "payment", to: "commerce", label: "alt：部分 Capture 返回 PARTIAL_CAPTURE_REVERSAL_NOT_SUPPORTED，V1 不自动组合 Void 未捕获余额与 Refund 已捕获金额", kind: "sync" },
    ],
  },
